class Solution {
    private long count(long bound,int limit,String suffix){
        if(bound<=0)return 0;
        String cap=Long.toString(bound);
        int totalLength=cap.length(),suffixLength=suffix.length();
        long answer=0;
        for(int length=suffixLength;length<=totalLength;length++){
            boolean fullLength=length==totalLength;
            long[] dp={
                0,1
            };
            for(int position=0;position<length;position++){
                long[] next=new long[2];
                int forced=position>=length-suffixLength?suffix.charAt(position-(length-suffixLength))-'0':-1;
                for(int tight=0;tight<=1;tight++)if(dp[tight]>0){
                    int upper=tight==1&&fullLength?cap.charAt(position)-'0':9;
                    int lower=position==0?1:0;
                    if(forced>=0){
                        if(forced>=lower&&forced<=limit&&forced<=upper)next[tight==1&&fullLength&&forced==upper?1:0]+=dp[tight];
                    }else for(int digit=lower;digit<=Math.min(limit,upper);digit++)next[tight==1&&fullLength&&digit==upper?1:0]+=dp[tight];
                }
                dp=next;
            }
            answer+=dp[0]+dp[1];
        }
        return answer;
    }
    public long numberOfPowerfulInt(long start,long finish,int limit,String s){
        return count(finish,limit,s)-count(start-1,limit,s);
    }
}

