class Solution {
    private fun count(bound:Long,limit:Int,suffix:String):Long{
        if(bound<=0)return 0;
        val cap=bound.toString();
        val totalLength=cap.length;
        val suffixLength=suffix.length;
        var answer=0L;
        for(length in suffixLength..totalLength){
            val fullLength=length==totalLength;
            var dp=longArrayOf(0,1);
            for(position in 0 until length){
                val next=LongArray(2);
                val forced=if(position>=length-suffixLength)suffix[position-(length-suffixLength)]-'0' else -1;
                for(tight in 0..1)if(dp[tight]>0){
                    val upper=if(tight==1&&fullLength)cap[position]-'0' else 9;
                    val lower=if(position==0)1 else 0;
                    if(forced>=0){
                        if(forced>=lower&&forced<=limit&&forced<=upper)next[if(tight==1&&fullLength&&forced==upper)1 else 0]+=dp[tight]
                    }else for(digit in lower..minOf(limit,upper))next[if(tight==1&&fullLength&&digit==upper)1 else 0]+=dp[tight]
                };
                dp=next
            };
            answer+=dp[0]+dp[1]
        };
        return answer
    };
    fun numberOfPowerfulInt(start:Long,finish:Long,limit:Int,s:String):Long=count(finish,limit,s)-count(start-1,limit,s)
}

