class Solution {
    long long count(long long bound,int limit,const string& suffix){
        if(bound<=0)return 0;
        string cap=to_string(bound);
        int totalLength=cap.size(),suffixLength=suffix.size();
        long long answer=0;
        for(int length=suffixLength;length<=totalLength;++length){
            bool fullLength=length==totalLength;
            array<long long,2> dp={
                0,1
            };
            for(int position=0;position<length;++position){
                array<long long,2> next={
                    0,0
                };
                int forced=position>=length-suffixLength?suffix[position-(length-suffixLength)]-'0':-1;
                for(int tight=0;tight<=1;++tight)if(dp[tight]){
                    int upper=tight&&fullLength?cap[position]-'0':9,lower=position==0?1:0;
                    if(forced>=0){
                        if(forced>=lower&&forced<=limit&&forced<=upper)next[tight&&fullLength&&forced==upper]+=dp[tight];
                    }else for(int digit=lower;digit<=min(limit,upper);++digit)next[tight&&fullLength&&digit==upper]+=dp[tight];
                }
                dp=next;
            }
            answer+=dp[0]+dp[1];
        }
        return answer;
    }
    public:long long numberOfPowerfulInt(long long start,long long finish,int limit,string s){
        return count(finish,limit,s)-count(start-1,limit,s);
    }
};
